  name: string;
  use: string;
  brand: string;
  viewBox: string;
  /** stroke width in viewBox units, so every outline reads at the same weight */
  stroke: number;
  /** filled with the brand colour on hover */
  shape: string[];
  /** filled white on hover (marks set on a brand-coloured tile) */
